from dataclasses import dataclass
from adaptix import Retort, name_mapping, NameStyle, DebugTrail
from adaptix.load_error import LoadError
@dataclass
class A:
    first_name: int
    second: int = 3
for debug in DebugTrail:
    r = Retort(recipe=[name_mapping(aliases={'first_name': ('old', 'older')}, alias_style=NameStyle.CAMEL)], debug_trail=debug)
    assert r.load({'old': 2}, A) == A(2)
    assert r.load({'firstName': 2}, A) == A(2)
    try: r.load({'old': 2, 'older': 3}, A)
    except LoadError: pass
    else: raise AssertionError(debug)
    try: r.load({'old': 'bad'}, A)
    except Exception as e: print(debug, repr(e))
    else: raise AssertionError(debug)
print('alias probes passed')
